#!/bin/sh
# Resolves the profile blocks of a template .md: each plan gets a text with no dead branches.
# A block opens on a line that is only {{#full}} or {{#lean}} and closes on the line that is
# only {{/full}} or {{/lean}}; the block of the requested profile stays (without the marker
# lines), the other one goes away. The other {{…}} markers (NAME, PATH, CONVENTIONS) stay as
# they are.
# Usage: sh <template>/profile.sh <full|lean> <source.md> <destination.md>
# Exits 0 when it wrote the destination; 1, without writing, if a block is never closed, is
# closed without being opened or opens inside another; 2 on wrong usage. The messages come
# out in the package language.

language='en'
# >>> strings (area profile.): generated by tools/script-strings.sh from core/i18n/*.json; do not edit by hand
case "$language" in
  [Xx]-[Tt][Ee][Ss][Tt]) msg_language="x-test" ;;
  [Pp][Tt]-[Bb][Rr]) msg_language="pt-BR" ;;
  [Pp][Tt]|[Pp][Tt]-*) msg_language="pt-BR" ;;
  *) msg_language="en" ;;
esac
# shellcheck disable=SC2016,SC2089 # backticks and quotes in the strings are text, not expansion
case "$msg_language" in
  x-test) MSG_TABLE='profile.usage	x-test:profile.usage
profile.unknown	x-test:profile.unknown {0}
profile.missing	x-test:profile.missing {0}
profile.openInside	x-test:profile.openInside {0} {1} {2}
profile.closeWithoutOpen	x-test:profile.closeWithoutOpen {0} {1} {2}
profile.noClose	x-test:profile.noClose {0} {1}
' ;;
  pt-BR) MSG_TABLE='profile.usage	Uso: sh profile.sh <full|lean> <origem.md> <destino.md>
profile.unknown	profile.sh: perfil «{0}» desconhecido; os perfis são full e lean
profile.missing	profile.sh: falta {0}
profile.openInside	profile.sh: {0}:{1}: bloco aberto dentro do bloco {2}
profile.closeWithoutOpen	profile.sh: {0}:{1}: fecho sem abertura: {2}
profile.noClose	profile.sh: {0}: bloco {1} sem fecho
' ;;
  *) MSG_TABLE='profile.usage	Usage: sh profile.sh <full|lean> <source.md> <destination.md>
profile.unknown	profile.sh: unknown profile "{0}"; the profiles are full and lean
profile.missing	profile.sh: {0} is missing
profile.openInside	profile.sh: {0}:{1}: block opened inside block {2}
profile.closeWithoutOpen	profile.sh: {0}:{1}: close without an opening: {2}
profile.noClose	profile.sh: {0}: block {1} is never closed
' ;;
esac
# shellcheck disable=SC2090 # a table read by awk from the environment, never split by the shell
export MSG_TABLE
MSG_AWK='
function msg_load(   m, ls, j, p) {
  msg_ok = 1
  m = split(ENVIRON["MSG_TABLE"], ls, "\n")
  for (j = 1; j <= m; j++) { p = index(ls[j], "\t"); if (p > 0) MSG[substr(ls[j], 1, p - 1)] = substr(ls[j], p + 1) }
}
function msg(k, a0, a1, a2, a3, a4, a5,   s, r, i, c) {
  if (!msg_ok) msg_load()
  s = (k in MSG) ? MSG[k] : k
  r = ""
  while ((i = index(s, "{")) > 0) {
    c = substr(s, i + 1, 2)
    if (c ~ /^[0-5][}]$/) {
      c = substr(c, 1, 1)
      r = r substr(s, 1, i - 1) (c == "0" ? a0 : (c == "1" ? a1 : (c == "2" ? a2 : (c == "3" ? a3 : (c == "4" ? a4 : a5)))))
      s = substr(s, i + 3)
    } else { r = r substr(s, 1, i); s = substr(s, i + 1) }
  }
  return r s
}
'
msg() { awk "$MSG_AWK"' BEGIN { print msg(ARGV[1], ARGV[2], ARGV[3], ARGV[4], ARGV[5], ARGV[6], ARGV[7]); exit }' "$@"; }
# <<< strings

profile=$1 source=$2 destination=$3
if [ $# -ne 3 ] || [ -z "$destination" ]; then
  msg profile.usage >&2
  exit 2
fi
case "$profile" in
  full|lean) ;;
  *) msg profile.unknown "$profile" >&2; exit 2 ;;
esac
[ -f "$source" ] || { msg profile.missing "$source" >&2; exit 2; }

tmp="$destination.profile-tmp"
if awk -v profile="$profile" -v file="$source" "$MSG_AWK"'
  function fail(k, a) { print msg(k, file, NR, a) > "/dev/stderr"; failed = 1; exit 1 }
  /^\{\{#(full|lean)\}\}$/ {
    if (block != "") fail("profile.openInside", block)
    block = substr($0, 4, 4); next
  }
  /^\{\{\/(full|lean)\}\}$/ {
    if (block != substr($0, 4, 4)) fail("profile.closeWithoutOpen", $0)
    block = ""; next
  }
  block == "" || block == profile { print }
  END { if (!failed && block != "") { print msg("profile.noClose", file, block) > "/dev/stderr"; exit 1 } }
' "$source" > "$tmp"; then
  mv "$tmp" "$destination"
else
  rm -f "$tmp"
  exit 1
fi
